quests[81909] = { id = 81909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolute Power", description = "The dark allure of this item surpasses my initial expectations. I can sense a surge of power coursing through me. \n\nWe must delve deeper into its mysteries.\n\nHowever, it is unwise to discuss this matter openly. Follow me inside, where we may deliberate further.", progress = "What's that you have there?", completion = "This is most unexpected. Where on earth did you find it?", objectives = "Discuss the tinderbox's destruction with Ct'nak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81910] = { id = 81910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Responsibility", description = "To witness such corruption is deeply unsettling. \n\nDespite the dark energies intertwined with this tinderbox, there remains a flicker of the Sacred Flame, struggling to escape. I will not destroy that flicker, champion. \n\nYet I dare not hold onto it any longer. \n\nPerhaps your purity of spirit can withstand the darkness it holds. Please, {name}, carry it with you. Protect that small spark of purity, and help it break free of the dark magic that ensnares it.", completion = "I place in your care this small ember of hope, along with the weighty responsibility to safeguard it.", objectives = "Accept the tinderbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81912] = { id = 81912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training 102", description = "Dunnae think I had nae noticed those rooks spittin' lightnin'. Sure beats tossin' hammers. But it won't mean nothin' if the Stormriders can't hit what they're fightin'.\n\nLet's test their aim. Got some gnomish contraptions here that'll project easy targets for practice. Take Shraubendre back out there an' show them how it's done!", progress = "Flyin' takes a firm hand. An' boy do these earthen have that!", completion = "Now, that's the stuff! Did a real number on those projectors. But what we really need is a movin' target.", objectives = "Help Kurdran train recruits in aerial targeting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81913] = { id = 81913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training 103", description = "These recruits seem tae be up for a challenge. Let's find them somethin' with a little bite!\n\nI saw a poor giant just off shore bein' pestered by a swarm of flying devils. Let's see if these rooks can shoot the wings off 'em an' provide some relief.\n\nYou and Shraubendre are settin' a good example for the rest. Keep it up!", completion = "The training went well, did it? I'm sorry I wasn't there for it. There was just something I had to do.", objectives = "Help Kurdran train recruits in aerial combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81914] = { id = 81914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dhar Oztan", description = "I love the stormrooks. Taking care of them was my directive, so they're all I've ever known. But even so, there are questions about them that even I don't have answers to.\n\nBaelgrim--Stormward Baelgrim--he was the expert. I'd pester him about them at every opportunity. And he shared what he could.\n\nHe told me once about summoning rooks at Dhar Oztan. It's an old Stormrider outpost that predates the Stormperch. If you want to know more about stormrooks, that's where we need to go.", completion = "So Baelgrim is gone. And now others have come. You mean to summon more rooks, don't you?", objectives = "Travel to Dhar Oztan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81915] = { id = 81915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home to Roost", description = "You've already done us a great service here, {name}. We will carry on by the example you have set.\n\nYou should return to Dhar Oztan and see to these new Stormriders you've recruited. They will undoubtedly benefit from the same diligence you have shown here.\n\nAnd, you can get away from these two and their posturing. I envy you, {name}...", completion = "It's good to have you back. Did all go well with the ground forces?\n\nWe're just about ready to start flight training here.", objectives = "Return to Dhar Oztan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81928] = { id = 81928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of the People", description = "As you might have heard, things haven't gone as intended for the citizens of the Silken Ward. The Pale Weavelashers have been keeping a tight grasp on the citizens. \n\nI wasn't able to find much before an Ascended kicked me out for snooping around. You are a fresh face, go around the Silken Ward and speak to the citizens, see if you can find a way to help them.\n\nAlso seek out Alchemist Talbax. I heard his name spoken a few times. He could be a useful contact.", progress = "The Silken Ward was supposed to be a new start for these people. Let's see what we can do to help.", completion = "Ah so you have heard about my recent troubles, friend. You may be able to help.", objectives = "Speak with 3 Silken Ward citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81929] = { id = 81929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here's the Plan", description = "{name}, the time has come to deal with the nerubian army. General Zev'kall is massing a sizeable force to the east. He intends to breach the wall and invade Hallowfall. There isn't much time.\n\nWe do not have the strength for an all-out assault. To that end, the Weaver has sent Gazlowe here to assist us. I'm willing to do what it takes to save my people.\n\nAnd as fate would have it, I have a personal matter to attend to while we are there.", progress = "I'm learning not all nerubians are bad or the same. I just hope the three of us are enough.", completion = "I think the three of us will be enough for this. Lean and mean, right?", objectives = "Help Faerin prepare while she explains her plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81930] = { id = 81930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Within", description = "People are experiencing visions of a \"Radiant Song\" all across Azeroth. We have reason to believe it's a warning of some kind.\n\nMeet me in Silithus. Perhaps Azeroth's Speaker can shed some light on what this warning might mean.", progress = "These visions grow stronger by the day.", completion = "We're all here. Good. Let's find out what the Radiant Song is trying to tell us.", objectives = "Go to Silithus to talk with Jaina about the visions spreading across Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81945] = { id = 81945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Arathi's End", description = "We will regroup on the outskirts of Arathi's End to the east.\n\nTheir forces are nearly ready and there isn't much time, {name}.", completion = "You made it. Now let's see if we can make a dent in these nerubians and save Hallowfall.\n\nI can already taste the rewards!", objectives = "Regroup with Faerin and Gazlowe at Arathi's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81950] = { id = 81950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BOOM Treats!", description = "If we're gonna stop this invasion, we need to take out their big guns. In this case, big guns equals ballistae.\n\nRemember how I had ya pick up them Betelsnax? Yeah, I didn't do that for no good reason. See, the nerubians here have their beetles haul their bombs. And those haulers love them some snacks. I mean, who doesn't?\n\nYou place the snacks next to a ballista, then a bomb beetle walks up, and BOOM!", progress = "Those ballista ain't gonna destroy themselves, ya know?!", completion = "Couldn't have done it better myself. Well, maybe. Actually, probably.\n\nBut still, we got the job done and at the low-low price of an over-inflated bag of processed junk that who knows what's in it?", objectives = "Place Betelsnax to lure bomb-laden beetles into destroying Nerubian Ballistae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81959] = { id = 81959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting a Concoction", description = "The Pale Weavelashers did indeed throw my alchemical supply down the cliffside. The potions will give the citizens of the Silken Ward the edge they need to rise up.\n\nI need someone to go down the Whispering Cliffs and collect any bottles that haven't broken open. I would go myself but the kobyss have made the area a hunting ground and I'm no fighter.\n\nThis would be a simple task for one such as yourself, eh?", progress = "The kobyss are beyond a nuisance. I need to get my Brightshade Potions back.", completion = "I hope you got my Brightshade Potions, eh? Without them I've got nothing left.", objectives = "Collect 8 Brightshade Potions in the Whispering Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81962] = { id = 81962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nudge in the Right Direction", description = "Wonderful, wonderful! Now that we have recovered my Brightshade Potions, I want you to go around the Silken Ward and show them off!\n\nThis will draw the ire of the Pale Weavelashers, I'm sure, but I want to show the populace that we don't need to live under their thumb. With a little aggressive motivation we can strike out on our own.\n\nYes, yes, this will do! Go around the Silken Ward and kill Pale Weavelashers. My potions will provide an extra kick the citizens will certainly love.", progress = "Be wary of any side effects the potions might have so I can document them.", completion = "The potions work wonders, don't they?", objectives = "Kill 10 Pale Weavelashers around the Silken Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81963] = { id = 81963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fruits of Our Labor", description = "You put on quite the show, yes? The orders are already coming in. The citizens can't wait to get their mandibles on the potions.\n\nI have one final task for you. I want you to take these latest orders and deliver them. You will accept, yes? \n\nThe citizens are stirring. Now is the time to show the Pale Weavelashers what we can do. If any try and stop you, you know what to do.", progress = "The time is now, friend. The Pale Weavelashers aren't unstoppable.", completion = "Well done, friend. The citizens have all they need to overcome the Pale Weavelashers.", objectives = "Deliver 3 Brightshade Potions to Silken Ward citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81964] = { id = 81964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blacksmith's Fate", description = "While we're here, I must find out what happened to my old friend, Ryton Blackholme. He was Hallowfall's finest blacksmith--and he was taken in a surprise nerubian attack. I could not save him.\n\nI searched for him, but found nothing except for his bloodied helm. I'd given up hope. But recently, I heard rumor about a blacksmith from a survivor who'd been pulled down off the Aegis Wall.\n\nCould it be Ryton? Will you help me, {name}?", progress = "Thank you for your help with this, {name}.", completion = "I can't believe Ryton is really gone, but it means the world to finally know what happened to my dear friend.\n\nWe will honor him as soon as we've dealt with Zev'kall's monstrosity.", objectives = "Assist Faerin Lothar to uncover the fate of Ryton Blackholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81965] = { id = 81965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Disruption", description = "While we cannot eliminate the nerubian threat here, we can disrupt their invasion plans.\n\nThere are any number of opportunities to accomplish our goal. Let's see what kind of damage we can do.", progress = "The more we can accomplish here, the safer we make things for Hallowfall.", completion = "That's enough for now. We'll need to periodically return to weaken their forces until there's another solution.", objectives = "Disrupt the nerubian invasion efforts at Arathi's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81966] = { id = 81966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slept Like a Rock", description = "Champion, Da's awake. Please return to Dalaran.", completion = "Welcome back Champion.", objectives = "Return to Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81969] = { id = 81969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to the End", description = "I want to honor my friend. But first, we need to deal the killing blow to this Light-forsaken place.\n\nIt's known that General Zev'kall has been overseeing the creation of a monstrosity... a void-corrupted, malformed nerubian. The scouting report pinpointed the location at the top of the canyon.\n\nWe're going to deprive him of his horrific pet. That should put an end to his plans to invade Hallowfall. At least for a little while longer.", completion = "Thank you, {name}. The people of Hallowfall are in your debt.\n\nI have one last thing to ask if you're willing.", objectives = "Work with Faerin and Gazlowe to take down the monstrosity known as Surek'tak the Sundered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81976] = { id = 81976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bazaar, Isn't It?", objectives = "Got any Bronze? Come spend it at the bazaar!\n\nThis will get you there. First one's free!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81981] = { id = 81981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Army?" }
quests[81984] = { id = 81984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Push Back the Dark", description = "Now that you're done with the level up campaign, you can help test the max level faction feature for Hallowfall, Push Back the Dark!\n\nOnce you accept my gossip, you will be teleported to a farm in desperate need of help. It is falling to the darkness, and could use your help putting this to rights again. Relight the keyflames and help the farmers... if you dare!\n\n(Accepting the gossip will level you to 80 and teleport you.)", objectives = "Talk to Captain Placeholder and accept his challenge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81985] = { id = 81985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul Memory: The Worldcarvers" }
quests[81990] = { id = 81990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Call", description = "Attention, residents of Hallowfall!\n\nUrgent assistance is needed to reclaim the shadowed outskirts.\n\nAs darkness grips countless family farms, your aid is needed to ignite the sacred flame and restore safety to our lands.", completion = "We are glad to have your support. Anything you can do to help re-ignite these keyflames will help!", objectives = "Report to Keyrra Flamestonge for further service.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81993] = { id = 81993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stormrider's Bond", description = "This beauty is no ordinary gryphon. It's got the storm within it. I've been trying all day tae calm it down.\n\nIt reminds me of an ol' Wildhammer myth. Stormrooks, they were called. Only able to be bonded by gryphon riders of great renown.\n\nIf we can show ye got the spirit of the storm, maybe it'll open up tae ye. Try proving yerself in battle.", progress = "I've never met such a stubborn gryphon before!", completion = "Look at that! I think it likes ye.\n\nHere, I found some gear in the stormrook's saddle. Looks perfect fer ye! And ye certainly deserve to wear something befitting a noble gryphon rider such as yerself.", objectives = "Collect 50 Storm Spirits by slaying powerful creatures of the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81994] = { id = 81994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sacred Connection", description = "Aye, the stormrook is beginning to take a liking to us. But the bond between rider and gryphon is forged over many trials.\n\nYe may have the spirit of the storm, but let's show how ye mastered it. Time to really prove yer mettle in battle.", progress = "I think I'm starting tae get this one to trust me.", completion = "Well, would you look at that! Ye truly have learned to master the storm within ye. A splendid gryphon rider if I ever did see one.\n\nAnd that's not all. I see the armor I gave ye is bristling with the heart of the storm now! Interesting...", objectives = "Collect 500 Storm Spirits by slaying powerful creatures of the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[81999] = { id = 81999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Home, New Candle!", description = "Janky hears there are giant fire bees on surface.\n\nFire bees make fire beeswax, yes? What if make candle from fire bee wax? What that be like?\n\nJanky must know!", progress = "What wait for?", completion = "Now just need way get wax without die...", objectives = "Meet Janky in the Cinderwold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82006] = { id = 82006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[82007] = { id = 82007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of Tails", description = "The newborn lynx have wandered off again!\n\nThose rascally cats are always up to mischief, darting off without a care. With Peevish missing and only Vesper and I to hold this position, your assistance would be a boon!\n\nI reckon those pesky felines are somewhere nearby. See if you can bring them back.\n\nI would use a light and search the cave, the spider-infested area to the south, and the coast to the north.", progress = "Have you found all the cats?", completion = "If these cat could talk they'd have quite the story to tell!\n\nIt looks as if one has taken a liking to you. I think you might have a new friend.", objectives = "Locate Beans, Beef, Thunder, and Cap'n Elaena. Then return them to Attica Whiskervale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82041] = { id = 82041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beledar's Blessing" }
quests[82042] = { id = 82042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Better Part of Valorstones", description = "Dornogal! A fascinating new place to everyone--not just the dracthyr!\n\nAnd fascinating new places have fascinating new reagents to find and study. Like Valorstones!\n\nI've seen similar objects all over Azeroth used to upgrade weapons and armor. I hypothesize these will work the same way.\n\nHelp my research by bringing me any Valorstones you collect. I'll upgrade a piece of your gear in return!", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! You are truly a supportive breeze in flight. Please take these tokens of thanks.", objectives = "Collect 50 Valorstones while adventuring in Khaz Algar, then return to Cuzolth and upgrade a piece of Season 1 equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82050] = { id = 82050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harbinger of Crests", description = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here.\n\nValorstones can only go so far, as I'm sure you know. You need these... Harbinger Crests to upgrade powerful adventuring gear. Much like Valorstones, these Crests are rewarded through many different activities. Harbinger Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Harbinger Crests, and we can help you upgrade some gear further.", progress = "If you're having a hard time finding Weathered Harbinger Crests, you can search for hidden treasures around Khaz Algar or those underground areas I've heard about. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power! And to advance my research, of course. But yes, your power growth!", objectives = "Acquire 15 Weathered Harbinger Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82059] = { id = 82059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transmutation Station", description = "My friend, these Crests are magnificent. It seems they can be transformed into different levels of Crest!\n\nIf you find yourself with a multitude of a lower-strength crest, you can upgrade it for a more powerful one! I think. I'm still working on that. I'll let you know when I figure it out. But we can transmute to weaker Crests right now!\n\nSee for yourself. Here's a few Carved Harbinger Crests. Speak to me and I can transform them into Weathered Harbinger Crests, all without excess energy or entropy!", progress = "If you lose those Carved Harbinger Crests, you can find more from powerful creatures around Khaz Algar. I've heard there's quite a variety of them!", completion = "See? Isn't it remarkable?\n\nI will let you know soon as I figure out how to turn Weathered Harbinger Crests into Carved Harbinger Crests. If my experience with other Crests is any guide, it will takes more of the Weathered Harbinger Crests to go that direction. But weakening Crests? That's easy!", objectives = "Bring 15 Carved Harbinger Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Harbinger Crests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82080] = { id = 82080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you are timed and have a LOT more braziers to hit.\n\nReady?", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82087] = { id = 82087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nStand near the bonfire and you'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers, then come back here... for your next lesson.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82088] = { id = 82088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobyss Kibosh" }
quests[82105] = { id = 82105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nAs you approach the bonfire you'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers then come back here... for your next lesson.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82109] = { id = 82109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82120] = { id = 82120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool Cleaner" }
quests[82121] = { id = 82121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demand Satisfaction", description = "We have worked together for some time now, {name}. I hope you have come to respect my vision as it pertains to the art of warfare. There are, as ever, rules that must be followed. Lines that must not be crossed.\n\nZev'kall has to die, and I have to be the one to do it. Every day that Ascended ruffian tramples upon the ideals of war tarnishes the legacy of our kingdom.\n\nPlease, do this last thing for me. Travel to the enemy stronghold and plant this flag on its steps. We will do this the correct way.", progress = "Make haste. I would see this tale end sooner rather than later.", completion = "Even Zev'kall would not dare to dismiss a formal challenge.\n\nGood.", objectives = "Plant Anub'azal's Standard inside the Siegehold in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82122] = { id = 82122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duel of the Fates", description = "I am no hapless rube, {name}. I do not expect Zev'kall to honor the nature of this challenge in even the most nominal sense.\n\nWe are in the enemy's fortress, and we are surrounded by his teeming sycophants. There will be interference.\n\nI have two orders for you, soldier. First, you will ward off any malcontents who wish to interrupt the duel. Second and more importantly, you will bring neither sword nor spell to bear against Zev'kall himself.\n\nHe will fall by my claws.", completion = "It is done.", objectives = "Defend Anub'azal from Zev'kall's minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82123] = { id = 82123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The General's Conviction", description = "<Anub'azal retches roughly. Ichor spews from his disjointed maw.>\n\nMy cohort's obligation to the Severed Threads yet remains. You would do well to report what happened here to the Weaver. Vexing as she is, she will have some idea of how to proceed from here.", completion = "So, that is what happened.\n\nDamnable fool. What was he thinking? Still... Zev'kall's death is a mighty blow to the loyalist forces. Chitin-headed as he is, I cannot question Anub'azal's strength.\n\nHis scions will take up his work for the Threads, and he will be remembered as a fine general.", objectives = "Inform Widow Arak'nai of what transpired.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82124] = { id = 82124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beginning of the End", description = "Queen Ansurek has been busy since the assassination attempt. Her grip is tightening on Azj-Kahet and her ever loyal nobles attend to her darkest whims. \n\nOn behest of the Queen, her two most loyal nobles Skeinspinner Takazj and Anub'arash, have locked down the Umbral Bazaar. \n\nTakazj's insufferable propaganda machinations and Anub'arash's increased military presence have painted a clear picture, ascend or die.\n\nI need you to go to the Umbral Bazaar and disrupt their hold.", progress = "How disappointing that Queen Ansurek continues to lead us to darkness.", completion = "The Queen's grip loosens and Skeinspinner Takazj and Anub'arash look worse in her eyes. Two flies, one thread.", objectives = "Cause disruption in the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82125] = { id = 82125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spy Like Us", description = "Distressing news comes from the Burrows, a sinister plan is unfolding in the gutters below. Citizens of the ward have been disappearing at an alarming rate. \n\nSkeinspinner Takazj and Anub'arash have all the subtlety of a hammer. I doubt it is their work. This is the hand of someone more subtle.\n\nI have a contact in the Burrows. His name is Gut'usul. Meet with him in the Burrows and find out what is going on down below.", completion = "It's about time someone showed up to help. You are the one the Vizier sent, yes?", objectives = "Meet with Gut'usul in the Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82126] = { id = 82126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of the People", description = "The Vizier no doubt filled you in on some of the details. Citizens in the Burrows are missing, that much you know. \n\nBut whispers on the wind tell a bigger story. Our citizens are being taken to the Transformatory and never returned!\n\nWe must stop this at all costs. More have been taken but it's not too late for them yet. They are still being kept in the Burrows. Find them and free them.", progress = "Act swiftly, we may not have long before they are beyond our grasp.", completion = "The citizens of the Burrows are in your debt. Good work.", objectives = "Free 5 citizens in the Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82127] = { id = 82127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Prey", description = "These abductors are rounding up citizens and no one in the Burrows can stop them. I think it is about time somebody did something. \n\nThey stalk the Burrows thinking they are unseen but I can see them, we can all see them. It's just nobody here can oppose them. That is where you come in.\n\nHunt these abductors down and show them who is really the prey.", progress = "Hit the abductors extra hard for me.", completion = "I hope they squirmed in their last moments. I have no sympathy for those that turn on their own.", objectives = "Kill 8 Abductors in the Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82130] = { id = 82130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shot at the Top", description = "While you have been out, I've been keeping busy as well. \n\nYour exploits in the Burrows drew the attention of someone much higher up. A strange being wrapped in bandages, with a scent like despair.\n\nFortunately, this unusual monster is paying a visit all the way down in the Burrows to find out why their abductors are missing. Now is our chance to strike, and take down this whole operation.", progress = "Soon the Burrows will be free.", completion = "The word of your exploits has reached all the way up here. A sign of a good job.", objectives = "Kill the Master Abductor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82133] = { id = 82133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Documenting: Field Manual Edition" }
quests[82141] = { id = 82141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Kill a Queen", description = "Tightening her grip on the citizens is something I expected of the Queen but forcefully ascending the population of the Burrows is too far. \n\nQueen Ansurek has fallen far greater than I ever expected. I can't sit idly by and watch her lead our people to ruin.\n\nThe time is now. We must kill Queen Ansurek and lead the people to a brighter future. Otherwise who knows how far she will fall.", progress = "It fills me with sorrow that it has come to this.", completion = "I take no pleasure in regicide but it had to be done.", objectives = "Kill Queen Ansurek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82143] = { id = 82143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Dissonance", description = "Hannan is correct only in that my presence here is not... strictly allowed.\n\nBut this corruption echoes in my mind, like a disruptive chord in the otherwise pure song of the world. Like a cry for help.\n\nI must heed that call. I must follow the dissonance to its source and find the heart of it, so that I may discover how to cleanse it.\n\nJoin me.", progress = "You have proven to be formidable. I am sure we can find a way to eliminate what extractors we come across.", completion = "<Orweyna gives a concerned glance toward the cave.>\n\nWhen he agreed to come with me... I was supposed to watch over him. Make sure nothing bad happened.", objectives = "Meet Orweyna and Hannan outside the Salien Gutters cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82144] = { id = 82144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Road", description = "This is the only road to the elevator, he should have been here by now. \n\nUnless... he didn't take the road! He wouldn't want to be seen. \n\nHe has no idea how dangerous the deeps can be. We have to find him!", completion = "If he'd only told me sooner... stone-headed oaf. But if he's set on leaving, he'll need a guide. Not sure he knows how to put one foot in front of the other on his own.\n\nHis chronicle is already on a rook headed to Gundargaz. They'll take care of his stories. At least until he's had his fill of his own.\n\nMy oath is, and always was, to care for him. I can't do that if I keep him down here.\n\nThank you for helping him.", objectives = "Find Brennok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82145] = { id = 82145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Mosswool" }
quests[82146] = { id = 82146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Cinderbee Surge" }
quests[82153] = { id = 82153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embassies and Envoys", description = "We sailed for what seemed like an eternity. I must admit there were times when I worried we would arrive too late.\n\nBut seeing all of you, united and strong, has rekindled my hope.\n\nBefore we begin planning, we must set up a base of operations here in Dornogal.", completion = "Ye mean tae tell me ye have been an interior decorator this whole time an ye have been holdin' out on me?\n\nWell done, {name}.\n\nYe are rearrangin' me chambers when we get home, ye are.", objectives = "Set up your faction's embassy in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82154] = { id = 82154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Titanic Resurgence" }
quests[82155] = { id = 82155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Shadows Below" }
quests[82156] = { id = 82156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: When the Deeps Stir" }
