quests[82164] = { id = 82164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul Memory: Reign of the Old Gods" }
quests[82195] = { id = 82195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rust and Redemption", description = "As you approach, a rusty lever catches your eye, stubbornly stuck in its place. \n\n\"This thing hasn't moved in ages,\" you muse, as you feel the rough metal resist your touch. \n\nGlancing around, you note the oily sheen on the plantlike Crawlers. \"Perhaps a bit of natural lubricant would do the trick,\" you ponder, realizing that these flora foes might yield what you need to ease the lever's grip.", progress = "The lever remains immovable, its secret locked tight without the Crawler Extract.", completion = "With the Crawler Extract in hand, you approach the obstinate lever once more. \n\nA few drops of the viscous liquid, and the lever moves with ease, revealing new paths ahead.", objectives = "Collect 3 Pure Crawler Extracts from Underdrip Crawlers and Crawler Sproutlings within the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82197] = { id = 82197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reserve Rumpus" }
quests[82206] = { id = 82206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Shadows" }
quests[82207] = { id = 82207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul Memory: Descendant of Distant Waters" }
quests[82212] = { id = 82212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weak Lionfish" }
quests[82213] = { id = 82213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Batty Request", description = "I'll gather a selection of our major trade goods before we head out for the meet up, but I could use some help in gathering some additional items. \n\nLately we've been struggling with collecting the best bat meat in Hallowfall. Could you gather some before you come to Dunelle's Kindness?", progress = "Did you get the meat?", completion = "Excellent. We just haven't had the resources to pull people off the wall to gather the meat with all those wasps around.", objectives = "Collect 8 Shacklefang Leafnose Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82214] = { id = 82214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Does Anyone Like Wasps?", description = "We haven't been able to gather resources from this area due to hornets moving in. \n\nWe just haven't been able to spare the resources from the wall to deal with them. If you can, we'd all appreciate it.", progress = "Damn those hornets. Wasps were bad enough when they were the size of my finger.", completion = "Thanks, {name}. \n\nI hate those things. Seriously, who thought it was a good idea to have wasps the size of a lynx.", objectives = "Kill 10 Shacklefang Hornets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82215] = { id = 82215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regular Fiber", description = "There is a plant fiber that grows in Rumshackle and The Fangs that makes for an excellent rope. Because of the hornets, we haven't been able to collect it in a long time and are running very low in our supplies.\n\nWhile you are in the area, could you collect some?", progress = "The fibers are like magic. The ropes they make are strong, and supple.", completion = "Maybe your people would be interested in these fibers?\n\nThey make the best rope I have ever seen.", objectives = "Collect 5 Tough Ivy Fibers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82216] = { id = 82216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Economical Request", description = "I hear you've come from the surface? Did you meet the earthen?\n\nWe used to trade with them, but after the Day of Darkness we struggled to send envoys. Those we sent never made it back. Honestly, we thought that they had perished.\n\nI'm going to try reaching out again. I'd like for you to write a letter of recommendation, in case we did something to offend them.", progress = "I hope this goes well. We really need additional resources.", completion = "Thank you, I'll send a runner with this to the earthen. I pray they make it back safely. \n\nAnd... thank you for the information about trading with your people, I hope they'll join as well.", objectives = "Write a letter of recommendation in Mereldar in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82217] = { id = 82217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground Economics", description = "After the Day of Darkness, we haven't seen or heard from the earthen. I don't know why.\n\nWe used to be on good terms. I'd even have considered Merrix a friend, albeit an odd one. \n\nWe need this to go well.", progress = "We need this trade deal to go through.", completion = "Flames preserve me. That went better than I had hoped. \n\nThank you, once again. You have done us a great service.", objectives = "Assist the Arathi with trade negotiations in Dunelle's Kindness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82219] = { id = 82219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spice Up Your Life", description = "Flames blessing to you, {name}.\n\nTrade has been going well now the Ringing Deeps are safe once again and things have, relatively, calmed down. Despite that, our General still won't breathe easily. She's wound tight and it's not healthy. An unhealthy general leads to an unhealthy army. \n\nSo a day with the family. Can you pick some herbs for the meal? You'll want the big ones, don't bother with the small ones.", progress = "Herbs bathed in the light of Beledar have a fantastic taste.", completion = "These will be wonderful, well done.", objectives = "Gather 7 Light-Bathed Lotus in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82220] = { id = 82220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle Eye, Eagle Die", description = "The eagles out by the undersea have bathed in the light of Beledar, and it makes them particularly tasty.\n\nCould you get a few eagle fillets? Take this harpoon with you, they can be feisty.", progress = "Watch yourself. The eagles can easily injure you.", completion = "These look very juicy. Thank you, {name}!\n\nI'll ensure that these go towards a good meal for us.", objectives = "Collect 5 Eagle Fillets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82221] = { id = 82221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Dress", description = "A traditional Arathi family meal involves displaying the various medals, awards, and mementos of the family. Given my mother's illustrious career, it's taking quite a while. \n\nWould you mind helping with some of the decorations?", progress = "We have to get this meal right, my mother needs to unwind.", completion = "Thank you. There's a lot of history in these items. It's good to see them on display.", objectives = "Help the Steelstrikes decorate their house in Mereldar in preparation for the upcoming meal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82222] = { id = 82222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cooking With Style", description = "Sorry my daughter roped you into this. I'm sure you had better things to be doing. \n\nShe has terrible manners. I'll have to have words with whoever raised her.\n\n<The general's mouth twitches in a quick smirk.>\n\nStill, you are here. Would you like to join us for the more enjoyable activity? We're about to start cooking.", progress = "Why do they say a pinch of salt? Why not a handful? More ingredients has to be better.", completion = "Hah! Oh flames, I had forgotten how much fun cooking can be!\n\nI really needed that.", objectives = "Help the Steelstrikes cook a meal in Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82223] = { id = 82223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Home Cooked Meal", description = "Home-cooked stew. There is nothing like it in the world. \n\nI grant you, it might not be as tasty as the stew from the Empires Edge Inn. But it was cooked by family. That's what makes it great.\n\nJoin us. You have more than earned the right.", progress = "It's been such a long time since I had a meal with the entire family.", completion = "Ah, I needed this.\n\nYou are welcome to join us anytime, {name}.", objectives = "Have a meal at the Steelstrike House in Mereldar in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82224] = { id = 82224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check on the Compiler", description = "That's everything up here. Would you check on Brennok? Recitations can be stressful, I'm sure he'd appreciate the help.", completion = "I was just about to look for you.", objectives = "Check in on Brennok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82225] = { id = 82225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation Extravaganza" }
quests[82226] = { id = 82226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papers? Please!", description = "Hey pal, what's it gonna take to get you to leave me alone? \n\nHow about a trip? A POWER trip...\n\nI told Boss Sparkshot that I would man the worksite's...er, resort's! Yeah, that I would man the resort's front desk for a bit.\n\nCare to take my place? It's just your usual paper-pushing busy work. Check credentials, keep an eye out for corporate sabotage, call in the occasional air strike, etcetera, etcetera...\n\n<Garv has already fallen back asleep.>", progress = "You're in my shade, pal.", completion = "<Garv throws something at you without glancing up.>", objectives = "Check papers at the Overseer's Desk in Opportunity Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82229] = { id = 82229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Uncommon Request", description = "{name}, welcome to Bel'ameth. I wonder -- do you have time for a small favor?\n\nEarlier today, a young kaldorei named Kelestra came to see me. She sought permission to bury her family in a barrow den. An uncommon request, but I gave her my blessing and directed her to the Barrows of Reverie. \n\nShe looked... melancholy. After she left, it struck me that she might be the last of her family still alive. If you have the time, could you check on her?", completion = "<Kelestra is so preoccupied with her own thoughts, it takes her a few moments to notice you.>\n\nOh hello, I didn't see you there. Would you... do you have a moment?", objectives = "Meet Kelestra in the Barrows of Reverie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82234] = { id = 82234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Floral Flair for Every Ram" }
quests[82236] = { id = 82236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test" }
