quests[82245] = { id = 82245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friendly Thak" }
quests[82248] = { id = 82248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advance to Faerin", description = "I have a little morsel all wrapped up from a corner of my web. Shall I share it with you? It's sure to mean your doom, little {race}.\n\nVery well... I can smell your eager impatience. I've sent that little green blob of a goblin you call Gazlowe off to the northeast. He tells me the queen and high general are marshalling their elite shock troops. No doubt they are readying to invade Hallowfall.\n\nScurry off to your Lamplighter friend. I'm certain she will want to smash everything in sight.", completion = "The Weaver sent you directly? Somehow I'm now even more concerned.", objectives = "Speak with Faerin Lothar at Faerin's Advance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82254] = { id = 82254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquacalypse" }
quests[82256] = { id = 82256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing the Cataract's Creatures" }
