quests[82266] = { id = 82266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tower Washing Simulator" }
quests[82268] = { id = 82268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrowful Journey Home", description = "I intend to burn Ryton's breastplate and Sir Ashrealm's tinderbox at Mereldar. I would be honored if you would join me.\n\nWould you carry the breastplate there?", progress = "Thank you for that, {name}.", completion = "You have done the Arathi a great service this day. Please stay and help us pay our respects to Ryton and Sir Ashrealm.", objectives = "Do Faerin the honor of delivering Ryton Blackholme's Breastplate to Mereldar in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82284] = { id = 82284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remembrance for the Fallen", description = "It is our custom to pay homage to the fallen by burning whatever we can recover of their belongings. Usually, it is their tinderboxes as those are easier to carry. We then return those items to the flame.\n\nWhile we were able to retrieve Sir Ashrealm's tinderbox, Ryton's breastplate will serve to honor his memory.\n\nYou have placed your life in danger not only for me, but also for Hallowfall. I would be honored if you would assist me this one last time in remembering our fallen.", progress = "Thank you, {name}.", completion = "It is done. It feels both odd and somehow comforting to finally know my dear friend's fate with certainty.\n\nThank you for everything, {name}.", objectives = "Place the Breastplate and Tinderbox in the forge at Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82285] = { id = 82285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul Memory: A Wounded Soul" }
