quests[82296] = { id = 82296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Creation", objectives = "Ah, the Catalyst. It's a marvel that even words struggle to capture. \n\nPicture this, young one. Long before our city's foundations were laid, Titans roamed this land. Masters of the innovation, they forged wonders beyond imagination. And amidst their great works, they crafted the Catalyst.\n\nAnd now its very power belongs to you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
