quests[82335] = { id = 82335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82338] = { id = 82338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absent Errand", description = "Do you remember the logbook you discovered in Zev'kall's office? It contained critical information about Zev'kall's misuse of our people. I gave it to my assistant, Anub'okki, to bring to the historians in the Skeins.\n\nBut I have not heard back from Anub'okki. I suspect foul play. See if anyone in the Skeins will admit to having seen him!", completion = "Let us speak, but we must do it quietly.", objectives = "Seek out Anub'azal's student in the Skeins of Nerub'ar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82339] = { id = 82339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Honorless Kill", description = "If it will get you out of here sooner, I will tell you what I saw.\n\nI did not see what happened to Anub'okki. But I can tell you that corpses are dumped into Pillar-nest Xesh to be forgotten about. The cleanup crew dragged Anub'okki out of here not long ago. \n\nIf you hurry, you may be able to examine the remains before they are gone.", progress = "Did you find Anub'okki?", completion = "This dagger has a version of Zev'kall's new pheromones on the handle. I know that he was involved in this. Directly killing Anub'okki is one step too far.\n\nThe assassin also did not take the logbook back. Zev'kall is showing his hand: that he thinks I am powerless, even if I have blackmail information.\n\nThis will not stand!", objectives = "Recover the logbook and discover what happened to Anub'okki.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82340] = { id = 82340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loss of Limb", description = "Happy greetings! I am Mr. Sunflower, and this is my tea room and therapy space. It is a safe place for everyone!\n\nI wonder if you might be willing to help a patient of mine. Vi'azl is deathly afraid of creatures with fewer limbs. I think it has grown into a deep phobia of dismemberment. I'm trying to get to the bottom of this diagnosis. \n\nWould you speak to him, and demonstrate that you, who do not have eight limbs, are not so terrifying after all?", progress = "Vi'azl must have some terrible trauma related to creatures with fewer limbs. We must help him.", completion = "Oh dear. This is so much worse than I had originally diagnosed.", objectives = "Assist Mr. Sunflower in Vi'azl's therapy session.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
