quests[82365] = { id = 82365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crafter's Delight", objectives = "You are a valued asset to the Council, {name}. We request you accept this token of our gratitude, and henceforth be known as an Honorary Councilmember.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82367] = { id = 82367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth-Encrusted Gem", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82369] = { id = 82369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shining Bundle of Goods", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nNo, this candle not made from earwax. Made from beeswax! Smells so nice! You like nice smells, yes? If not, might want to step away from me, ha ha ha. Sorry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82370] = { id = 82370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crests", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82371] = { id = 82371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flickering Candle", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nYes, this candle made from my own earwax. You? Special. And \"you're welcome.\" Maybe next time, I can have some of your earwax? No pressure. Think about it! I'll wait.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
