quests[82452] = { id = 82452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: World Quests", description = "There so much to be done and so little time to do it!\n\nBrinthe and I have been gathering word of the people that need the most aid throughout all of Khaz Algar. There's too many to count!\n\nGo out and help them. With your aid, will can bring all our people closer together... so we may all grow stronger.", progress = "Strange, these notes that come from Azj-kahet. I am.. hesitant to send any aid to the nerubians. Not after what they've done to my people.\n\nBut between your reports and those from our scouts... perhaps we can use their... disagreements to our advantage. And perhaps some are truly in need of aid. Of kindness. \n\nI do not want my eyes to be clouded by hate. And yet... \n\n<Faerin sighs.> \n\nWho knows. All I do know I won't regret a kindness.", completion = "Ah! I've had so many scouts and letters already! You've done so well. I hope you know you are appreciated.", objectives = "Complete World Quests in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82453] = { id = 82453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Encore!", description = "Have you seen the fliers around? They're staging some earthen plays in the Proscenium!\n\nI can't remember the last time I've seen a play, but I've got my hands full, as usual. You'll go, right?\n\nI'm sure everyone here could use their spirits raised. A play might be just the thing everyone needs. Make sure it's a night to remember!", progress = "Once, when I was a kid, I decided to put a play on for my family!\n\n<Faerin grimaces.> \n\nIt didn't... it didn't go well.", completion = "Did you see the play? Was it good? Tell me everything.", objectives = "Participate in the Theater Troupe event and complete World Quests in Khaz Algar", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82454] = { id = 82454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebath Tuning" }
quests[82455] = { id = 82455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No More Bread" }
quests[82456] = { id = 82456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chew On This" }
quests[82465] = { id = 82465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Gems", description = "So, all they gave us was a location and a garbled riddle...\n\nBut I guess we know where to start.\n\nI can picture it now. Once I have Basalteous's knowledge, I will have nobles and merchants lining up outside my house. No, my mansion! \n\nThe earthen did say southwest, right? I will find the cave and meet you there. Quickly now!", completion = "Look at the walls of this cave. Look at all these gems! I can't believe it. The story must be real! \n\nI am going to be so, so rich. And influential. And powerful.\n\nI need to sit down for a moment and catch my breath.", objectives = "Meet Natalia by Basalteous's cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82466] = { id = 82466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Do For Gems", description = "According to the earthen, we have to lure the spirit. Or disturb it. Or something.\n\nThe four standing stones they mentioned have depleted elemental cores laying around them. There are igneous elementals outside and on the beach to the north. Are you thinking what I'm thinking? \n\nCould you get me elemental cores? Maybe just a few? We're so close, so we might as well try...", progress = "Do you have the cores?", completion = "Four cores for four standing stones. \n\nI am ready when you are.", objectives = "Collect 4 elemental cores from the Igneous Sand elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82467] = { id = 82467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gems Are Forever", description = "I am so close, I can feel it in my bones.\n\nPlace the cores next to each standing stone. It is time to summon Basalteous.", progress = "This is it. I can feel it.", completion = "That was almost effortless! For me, at least. \n\nCan you imagine what I can do with this knowledge? Can you imagine my name spoken in Stormwind? Gilneas? Maybe even Orgrimmar! \n\nI will be able to do and achieve everything I wanted. Everyone will finally look up to me. I will have all the gold for all I can find and create!", objectives = "Lure out Basalteous by placing a core by each standing stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82468] = { id = 82468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Win" }
quests[82470] = { id = 82470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Riddles" }
quests[82477] = { id = 82477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Farmhand", progress = "This'll keep our crops safe in the future. And perhaps the leftovers can go... in a stew.", completion = "Good work, {name}, that looks... edible. And when you're on the wall, worried about nerubians killing you, I doubt anyone will mind. \n\nI was able to get a lot of ELIZA's decision sprockets properly aligned while you were doing that, so thanks!", objectives = "Recover 8 Slightly Chewed Harvest Bounty from Gluttonous Jawcrawlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82478] = { id = 82478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regularly Scheduled Maintenance", progress = "These are from Orren? I think they go well together, even though they're so different.", completion = "Wow, that's really sweet of him. I'll be here for a while, dealing with the kobyss, but I should send something back. \n\nSo he knows I'm safe, and that I can't wait to see him.", objectives = "Take Orren's Message, 6 Crimson Charmer and 6 Amber Bloom to Aemyra at Velhan's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82479] = { id = 82479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sword is Mightier", progress = "Did you find Aemyra? Is she alright?", completion = "I'm really glad to hear she's okay! But I have a huge problem now.", objectives = "Help Aemyra choose the right words for her message to Orren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82480] = { id = 82480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Job Killing Robot Or...", progress = "Were you able to stop ELIZA?", completion = "ELIZA didn't work like I expected. But Aemyra believes I'll get it right... I'm going to keep trying. \n\nAnd when I do, lack of food won't be a threat to the Arathi--and lack of time won't keep me from Aemyra!", objectives = "Stop ELIZA.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82481] = { id = 82481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enforcer Extermination" }
quests[82482] = { id = 82482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Snuffling", description = "I've wanted to be able to explore beyond Hallowfall's caves for so long now. Of course, I hardly have time, but when I do... there's such surprises everywhere!\n\nTreasures, friends in need, foes great and small... All so wonderful. \n\nI'll just have to live vicariously through you. Deeds need doing! Go out and seek the surprises in every nook and cranny. I'm certain you will find things that need doing!", progress = "Oh, what have you found?! Tell me everything.", completion = "Our world is a wonderful place. Thank you for protecting it.", objectives = "Find Disturbed Earth piles to Snuffle and discover Worldsoul Motes by skyriding all around Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82483] = { id = 82483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Spreading the Light", description = "Darkness continues to spread through Hallowfall. We need your help to keep the fires burning!\n\nThe shadows are deep and dark. My people are strong, but we always need more hope. More sparks for the flame. You are the brightest spark of all.", completion = "<Faerin breathes deeply.> \n\nEven from here... I can almost feel it. Beledar's strength returning. You've helped push back the darkness. \n\nThank you.", objectives = "Complete Spreading the Light objectives and slay Rare creatures in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82485] = { id = 82485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Cinderbrew Meadery", description = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim.\n\nI can't help but imagine it's how Beledar would taste...\n\nThe earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands.\n\nBut... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", completion = "Did you get stung by any bees? Did you feel the burn? Maybe you're allergic.\n\n<Faerin chuckles.>\n\nWhat? That wasn't a funny enough joke? Then you do better!", objectives = "Complete the Cinderbrew Meadery dungeon on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82486] = { id = 82486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Rookery", description = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities!\n\nIt must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. \n\nLook into it, {name}.You will learn:", sourceObjective = "Complete the Rookery dungeon on Normal difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82487] = { id = 82487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Stonevault", description = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. \n\nI can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. \n\nEirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!", progress = "To corrupt your own people... I can't imagine how the old High Speaker could bear to do that.", completion = "Brinthe and I have heard word of your success! \n\nAs the new High Speaker, I'm sure Brinthe will lead her people with more grace than Eirich.", objectives = "Complete the Stonevault dungeon on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82488] = { id = 82488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Darkflame Cleft", description = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them!\n\nTheir little candles... keeping their little flames lit...\n\n<Faerin clasps her hand to her chest with a grin.> \n\nSo brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. \n\nReports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!You will learn:", sourceObjective = "Complete the Darkflame Cleft dungeon on Normal difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82489] = { id = 82489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Dawnbreaker", description = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. \n\nIt is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", completion = "Our ships are proof of the creativity and ingenuity of the Hallowfall Arathi.\n\nDespite all odds, we still strive to creative beauty. That's what I love most about my people.", objectives = "Complete The Dawnbreaker dungeon on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82490] = { id = 82490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Priory of the Sacred Flame", description = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some--\n\n<Faerin pauses, momentarily lost for words.>\n\nThere are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. \n\nBut things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people!\n\nThis isn't what the Light is about, {name}. Stop them.You will learn:", sourceObjective = "Complete the Priory of the Sacred Flame dungeon at Normal difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82491] = { id = 82491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Ara-Kara, City of Echoes", description = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. \n\nThere's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. \n\nWe need to find out what's going on. Bring together your strongest companions and investigate!", completion = "You're back! I was worried. Tell me everything.\n\n<Faerin looks you over.> \n\nThose spiders didn't... do anything to you, did they? Didn't... plant eggs under your cloak or something? \n\n<Faerin shivers.>", objectives = "Complete the Ara-Kara, City of Echoes dungeon on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82492] = { id = 82492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: City of Threads", description = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. \n\nWe must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", completion = "All those spiders. All those legs. \n\n<Faerin shivers.> \n\nI hope you fared well. Good work, {name}.", objectives = "Complete the City of Threads dungeon on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82493] = { id = 82493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Dawnbreaker", description = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. \n\nIt is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", progress = "How goes the preparations?", completion = "Our ships are proof of the creativity and ingenuity of the Hallowfall Arathi.\n\nDespite all odds, we still strive to creative beauty. That's what I love most about my people.", objectives = "Complete The Dawnbreaker dungeon on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82494] = { id = 82494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Ara-Kara, City of Echoes", description = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. \n\nThere's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. \n\nWe need to find out what's going on. Bring together your strongest companions and investigate!", completion = "You're back! I was worried. Tell me everything.\n\n<Faerin looks you over.> \n\nThose spiders didn't... do anything to you, did they? Didn't... plant eggs under your cloak or something? \n\n<Faerin shivers.>", objectives = "Complete the Ara-Kara, City of Echoes dungeon on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82495] = { id = 82495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Cinderbrew Meadery", description = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim.\n\nI can't help but imagine it's how Beledar would taste...\n\nThe earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands.\n\nBut... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", completion = "Did you get stung by any bees? Did you feel the burn? Maybe you're allergic.\n\n<Faerin chuckles.>\n\nWhat? That wasn't a funny enough joke? Then you do better!", objectives = "Complete the Cinderbrew Meadery dungeon on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82496] = { id = 82496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: City of Threads", description = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. \n\nWe must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", completion = "All those spiders. All those legs. \n\n<Faerin shivers.> \n\nI hope you fared well. Good work, {name}.", objectives = "Complete the City of Threads dungeon on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82497] = { id = 82497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Stonevault", description = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. \n\nI can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. \n\nEirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!", progress = "To corrupt your own people... I can't imagine how the old High Speaker could bear to do that.", completion = "Brinthe and I have heard word of your success! \n\nAs the new High Speaker, I'm sure Brinthe will lead her people with more grace than Eirich.", objectives = "Complete the Stonevault dungeon on Heroic difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82498] = { id = 82498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Darkflame Cleft", description = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them!\n\nTheir little candles... keeping their little flames lit...\n\n<Faerin clasps her hand to her chest with a grin.> \n\nSo brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. \n\nReports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!You will learn:", sourceObjective = "Complete the Darkflame Cleft dungeon on Heroic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82499] = { id = 82499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Priory of the Sacred Flame", description = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some--\n\n<Faerin pauses, momentarily lost for words.>\n\nThere are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. \n\nBut things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people!\n\nThis isn't what the Light is about, {name}. Stop them.You will learn:", sourceObjective = "Complete the Priory of the Sacred Flame dungeon at Heroic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82500] = { id = 82500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Rookery", description = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities!\n\nIt must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. \n\nLook into it, {name}.You will learn:", sourceObjective = "Complete the Rookery dungeon on Heroic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82501] = { id = 82501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Dawnbreaker", description = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. \n\nIt is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.You will learn:", sourceObjective = "Complete The Dawnbreaker dungeon on Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82502] = { id = 82502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Ara-Kara, City of Echoes", description = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. \n\nThere's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. \n\nWe need to find out what's going on. Bring together your strongest companions and investigate!You will learn:", sourceObjective = "Complete the Ara-Kara, City of Echoes dungeon on Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82503] = { id = 82503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Cinderbrew Meadery", description = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim.\n\nI can't help but imagine it's how Beledar would taste...\n\nThe earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands.\n\nBut... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.You will learn:", sourceObjective = "Complete the Cinderbrew Meadery dungeon on Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82504] = { id = 82504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: City of Threads", description = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. \n\nWe must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!You will learn:", sourceObjective = "Complete the City of Threads dungeon on Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82505] = { id = 82505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Stonevault", description = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. \n\nI can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. \n\nEirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!You will learn:", sourceObjective = "Complete the Stonevault dungeon on Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
