quests[82507] = { id = 82507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Priory of the Sacred Flame", description = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some--\n\n<Faerin pauses, momentarily lost for words.>\n\nThere are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. \n\nBut things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people!\n\nThis isn't what the Light is about, {name}. Stop them.You will learn:", sourceObjective = "Complete the Priory of the Sacred Flame dungeon at Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82508] = { id = 82508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: The Rookery", description = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities!\n\nIt must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. \n\nLook into it, {name}.You will learn:", sourceObjective = "Complete the Rookery dungeon on Mythic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82509] = { id = 82509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!You will learn:", sourceObjective = "Complete the Nerub-ar Palace raid on LFR difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82510] = { id = 82510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!You will learn:", sourceObjective = "Complete the Nerub-ar Palace raid on Heroic difficulty or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[82511] = { id = 82511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Awakening Machine", description = "The earthen tell me of this \"Awakening Machine\" that is part of their life cycle.\n\nIt imbues them with energy, once a gift of the titans but now from the Worldsoul.\n\n<Faerin smiles faintly and nods knowingly.>\n\nThey hold it in high reverence--as we do Beledar. \n\nI will fight to defend it with the same fervor as I would defend our own star! \n\nAid me, {name}. We can't let them down.", completion = "Wonderful! I know our earthen allies appreciate your aid.", objectives = "Defeat 20 cumulative waves of enemies in the Awakening Machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82512] = { id = 82512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: World Boss", description = "Hallowfall is not the only land beset by enemies. \n\nGreat monsters wander all of Khaz Algar--savage beasts and intelligent fiends alike. They murder Arathi, earthen, and adventurers in equal measure from innocent farmers to great warriors. \n\nI know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", progress = "I've seen monsters shifting in the distant darkness of Hallowfall. Things that haunt my nightmares.", completion = "How did you fare? Any new scars? Or new tales to tell?", objectives = "Defeat any World Boss and 5 rare creatures in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82516] = { id = 82516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Forging a Pact", description = "I've heard some reports of the goings on in Azj-Kahet. Nerubians have killed my people mercilessly since we arrived... it is very difficult to imagine them as allies.\n\nBut... I understand feeling... different from the rest of your people. Perhaps these nerubians who have interest in us are also... different. \n\n<Faerin sighs.> \n\nNo matter the cost... I can't bear to not give them a chance. Are they not also inhabitants of Khaz Algar?\n\nSee what aid you can bring them, my friend.", progress = "I want to believe some nerubians can be different... can be better. But please be careful.", completion = "Well, you look no worse for wear. I'm glad you didn't become spider food. \n\n<Faerin frowns and picks a scrap of web off your shoulder.>", objectives = "Select a Severed Threads Pact to represent in Azj-Kahet, complete objectives in their name, and slay rares in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82518] = { id = 82518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pipe Patcher" }
