quests[82539] = { id = 82539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Radiant Echoes", completion = "Thank you for answering my summons.", objectives = "Meet Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82540] = { id = 82540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Adventures Past", description = "It seems that Azeroth has grown... agitated? Something must have happened when Magni tried to commune with her. \n\nPast events have now come to life once more. I believe they're Azeroth's memories.\n\nMemories they may be, these Radiant Echoes are all too real and could cause serious danger if left unattended. I ask that you investigate one of them and help however you can.", progress = "Radiant Echoes and Radiant Visions, all appearing at once. What could Azeroth be trying to tell us? Or perhaps it's just... instinct.", completion = "Excellent work, {name}. Keep assisting with these Radiant Echoes and see if you can find a common thread. They must be connected somehow.", objectives = "Go the portrait room in Dalaran and use a glowing portal to join a Radiant Echoes event. Once it begins kill the area boss to complete the event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
